INSERT INTO pages (title,slug,content,show_in_footer,status,created_at) VALUES
('About Us','about-us','<p>DRESSY is a fashion house built on one idea: clothes should be well made, thoughtfully designed and easy to make your own.</p><h3>Our promise</h3><p>Premium fabrics, honest pricing and a service that treats every order like a gift. From everyday essentials to statement pieces - and a design studio where you can build a complete outfit and see it before you buy.</p><h3>Worldwide</h3><p>We deliver across Pakistan and to customers in the Gulf, Europe, North America and beyond.</p>',1,1,DATE_SUB(NOW(), INTERVAL 115200 MINUTE)),
('Shipping Policy','shipping-policy','<p>Domestic orders are delivered in 2-5 working days. International orders take 7-14 working days depending on destination and customs.</p><h3>Charges</h3><p>Domestic delivery is free on orders above the free-shipping threshold; otherwise a flat fee applies. International shipping is charged at a flat rate shown at checkout.</p>',1,1,DATE_SUB(NOW(), INTERVAL 115200 MINUTE)),
('Returns & Exchange','returns-exchange','<p>You may exchange an item within 7 days of delivery provided it is unworn, unwashed and has its tags attached.</p><h3>Not eligible</h3><p>Custom outfits and on-demand orders are made specially for you and are final sale unless faulty.</p>',1,1,DATE_SUB(NOW(), INTERVAL 115200 MINUTE)),
('Privacy Policy','privacy-policy','<p>We collect only the information needed to process your order and improve our store, such as your name, contact details, delivery address and anonymous visit statistics. We never sell your personal data.</p>',1,1,DATE_SUB(NOW(), INTERVAL 115200 MINUTE)),
('Terms & Conditions','terms-conditions','<p>By using this website and placing an order you agree to these terms. Prices and availability may change without notice. Orders are confirmed when our team contacts you or dispatches your parcel.</p>',1,1,DATE_SUB(NOW(), INTERVAL 115200 MINUTE)),
('FAQ','faq','<h3>How does Order on Demand work?</h3><p>Submit a request for any item - we quote a price and delivery time and you confirm only if you are happy.</p><h3>How do I use the Design Studio?</h3><p>Open Customize, choose jeans, a top and shoes, preview them on the mannequin and add the package to your bag.</p>',1,1,DATE_SUB(NOW(), INTERVAL 115200 MINUTE));
